INSERT OR REPLACE INTO programs (id, name, theme_concept, active) VALUES ('week1', 'Transit Cycle 01', 'MERIDIAN // OPS — long-haul transit vessel systems terminal', 1);
INSERT OR REPLACE INTO categories (id, program_id, name, label, sort_order) VALUES ('week1-propulsion', 'week1', 'propulsion', 'PROPULSION', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-0', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Bench press', '3 x 8 — Empty barbell (35 lb) only this week — focus: shoulder blades pinned, controlled descent to chest', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-1', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Powerblock row (bent over or single-arm)', '3 x 10 — 20-25 lb — squeeze shoulder blade, don''t yank with momentum', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-2', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Kettlebell overhead press (seated or standing)', '3 x 8/side — 10-15 lb — press straight up, don''t lean back. **Alternative:** since you can OHP the empty 35lb barbell for a few reps, feel free to use that instead 1-2x this week to see how it feels — or the fixed 15-20lb barbell as a middle option', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-3', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Pull-up bar: dead hang + scap pulls', '3 x max hang (aim 15-20 sec) + 8 scap pulls — Bodyweight — this builds shoulder stability before real pull-ups. **Given your trap/neck tendency:** keep shoulders pulled down away from ears the whole hang, don''t let them shrug up — if your neck/traps start to feel it, shorten the hang time rather than pushing through', 3);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-4', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Push-up progression', '3 x max effort (aim 5-8) — Incline push-ups: hands on the bench, feet on floor, **hands set wide** (you already know this helps you). Lower chest to bench, controlled. **Skip the knee push-up regression entirely** — with hypermobile kneecaps, kneeling on the floor under load isn''t worth it. Instead, progress by lowering the incline height (bench → lower surface → floor) rather than moving to your knees', 4);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-5', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Pulley face pulls', '3 x 15 — Light band/plate tension — elbows high, squeeze shoulder blades. **Given your trap/neck tendency:** keep the movement in the shoulder blades, not the neck/traps — if you feel it creeping into your neck, drop the tension further', 5);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-6', 'week1-propulsion', 'Day 1 (Tuesday) — Upper Body', 'Dumbbell bicep curl + tricep pushdown (pulley)', '2 x 12 each — EZ curl bar for curls (easier wrist angle than straight dumbbell curls, worth using given the hypermobility) + light pulley tension for pushdowns', 6);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-7', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Kettlebell goblet squat', '4 x 8 — 15-20 lb held at chest, **heels on squat wedges.** This is your main squat pattern this week, NOT the barbell. The wedges reduce how much ankle mobility you need to stay upright — if the forward lean was partly an ankle range issue, this alone may fix a lot of it. Sit back like sitting in a chair, chest up, weight even through the foot', 7);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-8', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Barbell squat (empty bar only)', '2 x 5 — 35 lb only, **heels on wedges, standing on the plywood platform.** Purely to practice bar position on back + the same upright-torso cue as the goblet squat, low reps', 8);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-9', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Kettlebell RDL / Romanian deadlift', '3 x 10 — 20-25 lb — hinge at hips, slight knee bend, feel hamstrings stretch, flat back. **Alternative:** since you have 2lb practice plates + 10lb plates, you could use the empty barbell (35lb) as a light RDL instead and add small increments over coming weeks — this lets you progress in much smaller jumps than jumping between kettlebell weights, which is genuinely useful given the hypermobility (smaller, more controllable load increases)', 9);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-10', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Glute bridge', '3 x 12 — If you don''t feel this in your glutes (common), try: feet closer to your hips, a resistance band looped just above your knees (push knees out against the band), and pause 2 sec at the top squeezing hard. If it''s still not landing, this exercise can be dropped for now — feeling it matters more than doing it', 10);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-11', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Split squat (rear foot elevated optional)', '2 x 10/side — Bodyweight or light dumbbells (5-8 lb each hand) — this covers the unilateral leg work walking lunges would, without needing lunge-length floor space', 11);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-12', 'week1-propulsion', 'Day 2 (Wednesday) — Lower Body (technique day)', 'Standing calf raise', '3 x 15 — Bodyweight', 12);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-13', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Powerblock incline press (feet up on bench or use floor angle)', '3 x 10 — 15-20 lb each hand', 13);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-14', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Pulley seated row', '3 x 12 — Moderate tension — squeeze at the back, controlled return', 14);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-15', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Powerblock lateral raise', '3 x 12 — 5-8 lb — light, controlled, no swinging', 15);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-16', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Negative pull-ups (jump to top, lower slow 3-5 sec)', '3 x 3-5 — Bodyweight — builds toward real pull-ups', 16);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-17', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Push-up progression', '3 x max effort — Same incline push-up as Monday — lower the incline (e.g., a lower surface) once 8+ reps feel easy at current height', 17);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-18', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Kettlebell suitcase carry', '3 x 20 steps/side — 20-25 lb — given the tight space, do this as a slow walk on the treadmill instead (very low speed, ~1 mph), holding the kettlebell at your side, core braced', 18);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-19', 'week1-propulsion', 'Day 4 (Friday) — Upper Body (volume day)', 'Dumbbell hammer curl', '2 x 12 — 8-12 lb', 19);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-20', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Kettlebell goblet squat', '3 x 10 — 15-20 lb — same cues as Tuesday', 20);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-21', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Kettlebell deadlift (standing over KB, or sumo stance)', '3 x 8 — 25-30 lb — hinge, flat back, drive through heels. **Stand on the plywood platform if it fits your stance**, otherwise plain carpet is fine here since it''s a lighter, more controlled lift than the squat', 21);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-22', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Walking lunge', '3 x 10/side — Given tight space, do **reverse lunges in place** instead (step back, not forward — needs less room, and is generally easier to balance for hypermobile knees since there''s less forward knee travel)', 22);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-23', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Hip thrust (feet on floor, shoulders on bench)', '3 x 12 — If you don''t feel this either (also common), try: band above the knees pushing out, feet a bit closer to your hips, chin tucked (not thrown back), and pause hard at the top. Same rule as the glute bridge — if it''s still not landing after trying these tweaks, it''s fine to drop for now', 23);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-24', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Side-lying leg raise or band walk', '2 x 15/side — Hip stability — helpful for knee tracking in squat', 24);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-propulsion-25', 'week1-propulsion', 'Day 5 (Saturday) — Lower Body (volume day)', 'Plank', '3 x 20-30 sec — Bodyweight', 25);
INSERT OR REPLACE INTO categories (id, program_id, name, label, sort_order) VALUES ('week1-fuel-cells', 'week1', 'fuel-cells', 'FUEL CELLS', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-0', 'week1-fuel-cells', NULL, 'Mon', '**Tofu & chickpea bowl:** 200g extra-firm tofu (cubed, air fry 12 min at 400°F with a little cornstarch + soy sauce) + 1 cup air-fried chickpeas + 200g roasted sweet potato + roasted veggies + tahini-lemon drizzle — Air fryer — 540 kcal / 32g', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-1', 'week1-fuel-cells', NULL, 'Tue', '**Ground turkey taco bowl:** 150g ground turkey browned in a pan (10 min) with chili powder, paprika, oregano + rice + black beans + lettuce, salsa, avocado — Stovetop, ~12 min — 550 kcal / 34g', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-2', 'week1-fuel-cells', NULL, 'Wed', '**Chickpea salad:** mixed greens, 1.5 cups chickpeas, cucumber, lactose-free feta (if available) or olives, pumpkin seeds, olive oil vinaigrette — No cook — 490 kcal / 24g', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-3', 'week1-fuel-cells', NULL, 'Thu', '**Red lentil dal:** 1.5 cups masoor dal (pressure cooker: red lentils, turmeric, garam masala, a little coriander, garlic, ginger — 5 min high pressure) over 2/3 cup rice — Pressure cooker — 480 kcal / 24g', 3);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-4', 'week1-fuel-cells', NULL, 'Fri', '**Meatball bowl:** 150g ground turkey or beef meatballs (air fry 10 min at 380°F) + roasted veggies + 2/3 cup farro or rice — Air fryer — 520 kcal / 33g', 4);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-5', 'week1-fuel-cells', NULL, 'Mon', '**Tofu steaks:** 200g tofu (pressed, air fry 15 min at 400°F, tossed in soy-ginger sauce) + roasted broccoli/carrots + 2/3 cup farro — Air fryer — 480 kcal / 30g', 5);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-6', 'week1-fuel-cells', NULL, 'Tue', '**Ground beef & veggie stir-fry:** 150g lean ground beef + mixed stir-fry veggies + garlic-ginger-soy sauce over 2/3 cup rice — Stovetop, ~12 min — 520 kcal / 32g', 6);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-7', 'week1-fuel-cells', NULL, 'Wed', '**Chana masala:** 1.75 cups chickpea curry (canned chickpeas, tomato, onion, turmeric, garam masala, light coriander — pressure cooker or stovetop 15 min) over 2/3 cup rice — Pressure cooker or stovetop — 500 kcal / 25g', 7);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-8', 'week1-fuel-cells', NULL, 'Thu', '**Turkey meatballs + marinara:** 150g ground turkey meatballs (air fry 10 min) in marinara over 2 oz Barilla Protein+ pasta or zucchini noodles — Air fryer — 500 kcal / 40g', 8);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-9', 'week1-fuel-cells', NULL, 'Fri', '**Black bean tacos:** 3 corn tortillas, 1.25 cups black beans (seasoned, quick stovetop), avocado, salsa, cashew crema or lactose-free sour cream — Stovetop, ~10 min — 500 kcal / 22g', 9);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-10', 'week1-fuel-cells', NULL, 'Sat', 'Repeat any favorite from the week — — — —', 10);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-fuel-cells-11', 'week1-fuel-cells', NULL, 'Sun', '**White bean & veggie soup:** pressure cooker (white beans, kale, tomato, garlic, 10 min) + slice crusty whole grain bread — Pressure cooker — 460 kcal / 23g', 11);
INSERT OR REPLACE INTO categories (id, program_id, name, label, sort_order) VALUES ('week1-life-support', 'week1', 'life-support', 'LIFE SUPPORT', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-life-support-0', 'week1-life-support', NULL, 'With breakfast (or mid-morning snack)', 'Multi + Omega-3 (Women''s), B-12 — Take with food for better absorption', 0);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-life-support-1', 'week1-life-support', NULL, 'With lunch', 'Calcium + D3 gummies — Separate from iron by a few hours (calcium blocks iron absorption)', 1);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-life-support-2', 'week1-life-support', NULL, 'With dinner or evening', 'Probiotic — Consistency matters more than exact timing — same time daily is the main thing', 2);
INSERT OR REPLACE INTO tasks (id, category_id, day_key, label, detail, sort_order) VALUES ('week1-life-support-3', 'week1-life-support', NULL, 'Only on days you haven''t had much red meat', 'Iron — Take with a vitaminC-containing food (citrus, berries) for better absorption, and **away from the calcium gummies and any Metamucil** by a few hours', 3);
